}
/** Independent ordinary-TypeScript oracle: no evaluator, interpreter, source output or snapshots. */
export function oracle(input, rows = plan(input), through = input.n) {
    let count = 0, source = 0;
    const values = [];
    const admitted = [];
    const outcomes = [];
    for (const row of rows) {
        if (row.position > through)
            break;
        if (row.kind === 'admit')
            admitted.push(row.actor);
        else if (row.kind === 'activate')
            source = row.source;
        else if (row.valid) {
            const amount = row.amount * (row.source === 1 ? 2 : 1);
            count += amount;
            if (input.growing)
                values.push(amount);
        }
